// The total of the ints from first up to, but not including, last.
int sum(const int* first, const int* last)
{
    int total{ 0 };
    for (const int* p{ first }; p != last; ++p)   // ++p moves on by one int
    {
        total += *p;
    }
    return total;
}

unitTests:
TEST("four numbers") {
    int values[4]{ 10, 20, 30, 40 };
    CHECK_EQ(sum(values, values + 4), 100);
}
TEST("part of an array") {
    int values[5]{ 1, 2, 3, 4, 5 };
    CHECK_EQ(sum(values + 1, values + 4), 9);
}
TEST("a single number") {
    int value{ 42 };
    CHECK_EQ(sum(&value, &value + 1), 42);
}
TEST("an empty run is zero") {
    int values[3]{ 7, 8, 9 };
    CHECK_EQ(sum(values, values), 0);
    CHECK_EQ(sum(values + 3, values + 3), 0);
}
TEST("negative numbers") {
    int values[3]{ -5, 5, -7 };
    CHECK_EQ(sum(values, values + 3), -7);
}

